import{_ as a}from"./chunks/daily-2026-08-22-agent-task-file-state-machine-figure-1.Cc3O206H.js";import{_ as i,C as n,o as s,c as o,E as r,a2 as c}from"./chunks/framework.Cm6XCzck.js";const f=JSON.parse('{"title":"How Does a Task Move Through an Agent Team? Claims, Execution, Review, and Completion in a File State Machine","description":"","frontmatter":{"title":"How Does a Task Move Through an Agent Team? Claims, Execution, Review, and Completion in a File State Machine","date":"2026-08-22","column":"open-source-engineering","category":"daily","article_type":"mechanism-analysis","edition":"research-center","research_question":"How can one task preserve identity and move legally through a file state machine and an engineering runtime into acceptance?","summary":"Body fields, lifecycle paths, reports, and acceptance decisions answer different questions. This article follows one task through FCoP and the CodeFlowMu V1.9.7 candidate implementation to expose the invariants that prevent cross-task binding, duplicate execution, and premature completion.","item_id":"MANUAL-20260822-AGENT-TASK-FILE-STATE","lifecycle":"Published","cover":"/assets/covers/daily-2026-08-22-agent-task-file-state-machine-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true,"sources":["research/manual-runs/2026-08-22-codeflowmu-rail-state-series-round1/02-source-register.md","research/manual-runs/2026-08-22-codeflowmu-rail-state-series-round1/02-fact-claim-matrices.md"]},"headers":[],"relativePath":"en/engineering/2026-08-22-agent-task-file-state-machine.md","filePath":"en/engineering/2026-08-22-agent-task-file-state-machine.md","lastUpdated":1787553126000}'),l={name:"en/engineering/2026-08-22-agent-task-file-state-machine.md"};function d(h,e,p,u,m,g){const t=n("ArticleCover");return s(),o("div",null,[r(t,{image:"/assets/covers/daily-2026-08-22-agent-task-file-state-machine-cover.png",kicker:"Open-source Engineering · Project Research",title:"How Does a Task Move Through an Agent Team? Claims, Execution, Review, and Completion in a File State Machine",summary:"Lifecycle paths, transition history, reports, and acceptance decisions carry different facts. Collapsing them into one done field creates cross-wiring and premature completion.",version:"MANUAL-20260822-AGENT-TASK-FILE-STATE",status:"Editorial & Visual PASS · 2026-08-23",languageHref:"/zh/engineering/2026-08-22-agent-task-file-state-machine",languageLabel:"中文"}),e[0]||(e[0]=c('<h1 id="how-does-a-task-move-through-an-agent-team-claims-execution-review-and-completion-in-a-file-state-machine" tabindex="-1">How Does a Task Move Through an Agent Team? Claims, Execution, Review, and Completion in a File State Machine <a class="header-anchor" href="#how-does-a-task-move-through-an-agent-team-claims-execution-review-and-completion-in-a-file-state-machine" aria-label="Permalink to &quot;How Does a Task Move Through an Agent Team? Claims, Execution, Review, and Completion in a File State Machine&quot;">​</a></h1><p>A task body says <code>status: done</code>, but the task file still sits in the active directory. A development report exists, yet the required compatibility evidence does not. The UI sees the report and releases a downstream deployment task. Which signal is authoritative?</p><p>The reliable answer is not to pick the field that looks most complete. These signals answer different questions: <strong>the path identifies the current lifecycle state; events record how the task moved; a report says what the executor returned; an acceptance decision says whether an authorized actor accepted it.</strong></p><p>This article follows one task through its full lifecycle and shows how a file state machine and an engineering rail cooperate. The deliverable is a set of invariants that can become tests, not merely a guide to directory naming.</p><blockquote><p><strong>Series order (2/3).</strong> <a href="./2026-08-22-codeflowmu-governance-state-rail">Part 1</a> defines the responsibility boundary among TMPA, FCoP, and CodeFlowMu. This article tests that boundary against task identity, lifecycle, dependencies, and concurrent claim. <a href="./../digital-employee/2026-08-22-agent-rail-decision-boundary">Part 3</a> defines which outcomes may be mechanical and which must remain accountable decisions.</p></blockquote><h2 id="do-not-compress-four-facts-into-one-done" tabindex="-1">Do not compress four facts into one <code>done</code> <a class="header-anchor" href="#do-not-compress-four-facts-into-one-done" aria-label="Permalink to &quot;Do not compress four facts into one `done`&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fact</th><th>Question answered</th><th>Typical carrier in this system</th></tr></thead><tbody><tr><td>Lifecycle state</td><td>Where is the task now?</td><td>FCoP <code>_lifecycle/</code> path</td></tr><tr><td>Transition history</td><td>Who changed the stage, when, and through which tool?</td><td>Append-only <code>transitions</code> entries in the TASK</td></tr><tr><td>Execution return</td><td>What did the agent submit, with what evidence?</td><td><code>REPORT-*</code></td></tr><tr><td>Acceptance</td><td>Did an authorized actor accept, reject, or request rework?</td><td>Lifecycle approval, independent REVIEW, or Runtime acceptance axis</td></tr></tbody></table><p>The facts may reference one another, but they are not substitutes. A report is not an approval. A body field is not the current path. A TASK in <code>_lifecycle/review/</code> does not prove that an independent <code>REVIEW-*</code> governance envelope exists.</p><p>The current <a href="https://github.com/joinwell52-AI/FCoP/blob/main/spec/fcop-v3-spec.md" target="_blank" rel="noreferrer">FCoP v3 specification</a> explicitly distinguishes these two meanings of review. The directory is a lifecycle stage for the TASK. A file under <code>reviews/</code> is a separate judgment about an artifact. Both may exist, but the protocol does not create an automatic one-to-one relationship.</p><p><img src="'+a+`" alt="Current file path, append-only transition history, reports, and acceptance decisions preserve different facts"></p><p><em>Figure 1. Current paths, transition events, REPORT artifacts, and acceptance decisions have different jobs. Physical time can assist an investigation but cannot alone establish causal order. Source: author synthesis from the FCoP v3 specification and CodeFlowMu V1.9.7 candidate evidence.</em></p><h2 id="a-task-in-five-stages" tabindex="-1">A task in five stages <a class="header-anchor" href="#a-task-in-five-stages" aria-label="Permalink to &quot;A task in five stages&quot;">​</a></h2><p>Use a request to add CSV export and run compatibility tests as the running example.</p><h3 id="_1-creation-establish-identity-before-admission" tabindex="-1">1. Creation: establish identity before admission <a class="header-anchor" href="#_1-creation-establish-identity-before-admission" aria-label="Permalink to &quot;1. Creation: establish identity before admission&quot;">​</a></h3><p>The PM creates a new task from an approved requirement. An FCoP TASK filename carries type, date, sequence, sender, and recipient, and the file enters <code>_lifecycle/inbox/</code>.</p><p>Creation means that the work object now exists. It does not mean an agent has claimed it or execution has begun. A team runtime also needs root-task, parent-task, and thread identity so that later children and reports return to the same responsibility tree.</p><h3 id="_2-claim-move-the-path-and-witness-the-transition" tabindex="-1">2. Claim: move the path and witness the transition <a class="header-anchor" href="#_2-claim-move-the-path-and-witness-the-transition" aria-label="Permalink to &quot;2. Claim: move the path and witness the transition&quot;">​</a></h3><p>When an authorized lifecycle tool claims the task, the TASK moves from <code>inbox</code> to <code>active</code>. The protocol requires a transition event with <code>from</code>, <code>to</code>, <code>by</code>, and <code>tool</code>.</p><p>FCoP&#39;s write-then-rename pattern does not edit the body, move the old file, and append a log as three loosely coupled actions. It prepares the destination content—including the new event—in a temporary file, persists it, and performs a rename within one filesystem boundary. The rename is the observable commit point.</p><p>POSIX.1-2024 specifies atomic directory-entry behavior for <a href="https://pubs.opengroup.org/onlinepubs/9799919799/functions/rename.html" target="_blank" rel="noreferrer"><code>rename()</code></a>: observers should see the old or new entry rather than an intermediate directory name. That guarantee has limits. It is not a cross-mount transaction, it does not by itself prove crash durability for all directory metadata, and it does not make a relaxed network filesystem strongly consistent.</p><p>There is one more boundary. If an implementation publishes a new destination file and only then removes the source, <code>rename</code> makes destination publication atomic; it does not turn destination publication and source removal into one cross-directory transaction. The two statements are not in tension: local-filesystem <code>rename()</code> makes <strong>one directory-entry replacement</strong> atomic, while a dual-stage conflict can arise only when the upper protocol composes “publish destination” and “remove source” as two interruptible operations. In a crash window, one TASK may remain in both <code>inbox/</code> and <code>active/</code>. “Paths address NOW; events record PAST” is not this article&#39;s rhetorical summary: <a href="https://github.com/joinwell52-AI/FCoP/blob/main/spec/fcop-3.0-spec.md" target="_blank" rel="noreferrer">FCoP v3 §§0.1, 1.4, and 2.3</a> explicitly separates current state, determined by path, from append-only <code>transitions</code> history and forbids deriving current state by replaying events. A reader must therefore <strong>not</strong> pick the directory with the apparently newer event. The correct behavior is to report and preserve the dual-stage conflict and stop projecting it as one current state; cleanup or recovery must use a later authorized lifecycle action.</p><p>The precise claim is therefore: <strong>rename can provide an atomic destination-publication point inside the declared filesystem boundary; it does not make an entire multi-agent system inherently concurrency-safe.</strong></p><h3 id="an-easy-to-miss-gap-complete-publication-is-not-exclusive-claim" tabindex="-1">An easy-to-miss gap: complete publication is not exclusive claim <a class="header-anchor" href="#an-easy-to-miss-gap-complete-publication-is-not-exclusive-claim" aria-label="Permalink to &quot;An easy-to-miss gap: complete publication is not exclusive claim&quot;">​</a></h3><p>This is not wordplay, but it is not the normal topology of the current local-first deployment. The tested CodeFlowMu V1.9.7 shape is <strong>one Runtime service for one local project root</strong>. Its controlled-restart record shows the current process holding the writer lock and retaining a consistent root binding. The inspected material does not declare two independent CodeFlowMu Runtimes sharing one project folder as supported, and it provides no dual-Runtime claim stress test. The following contention is therefore a boundary analysis for a future shared-workspace extension, not an assertion of an existing failure in the current single-Runtime local mode.</p><p>The boundary still matters because, in the public FCoP path, <code>claim_task</code> first reads whether a TASK is still in <code>inbox/</code>, then the <a href="https://github.com/joinwell52-AI/FCoP/blob/main/src/fcop/lifecycle/atomic.py" target="_blank" rel="noreferrer">atomic-commit implementation</a> publishes a temporary file into <code>active/</code> with <code>os.replace()</code>. If a future design allows agents A and B as independent claimants, and both pass the “still in inbox” check before the source is removed, both can construct a claim event from the same old content. A can publish first; B can publish later. POSIX-style replacement permits the later destination name to replace the earlier one, while both callers may treat their own call as successful and start work.</p><p>This does not turn a valid serial dependency graph into a genuine parallel branch. It creates a more dangerous <strong>false parallelism</strong>: one work item that should have one executor starts two agent sessions. The disk may retain only the later <code>active/</code> file, but that cannot retract the earlier tool call or code modification already started by the first agent.</p><p>The current write-and-replace path therefore solves “do not read a half-file”; it <strong>does not prove exclusive claim for a future multi-Runtime shared workspace</strong>. The public specification and inspected material do not provide evidence of a same-TASK double-claim stress test, a non-replaceable claim reservation, a lease, or heartbeat reclamation. This article must not describe them as existing features. If a future design explicitly permits competing claimants, the claim entry point needs a separate mutual-exclusion primitive: for example, a non-replaceable exclusive reservation (<code>O_CREAT | O_EXCL</code> where supported), or Runtime-side serialization/compare-and-swap against the canonical task identity. The primitive must be validated separately for Windows, local filesystems, and network filesystems; the local semantics of <code>link()</code>, a file lock, or <code>rename</code> cannot be generalized into a cross-platform guarantee.</p><p>Even a correct exclusive primitive answers only <strong>who won the physical race</strong>. It does not decide who was eligible to compete, which policy version authorized the claim, or whether the loser should wait, be denied, or enter reconciliation. Those are governance semantics. A lock added as an engineering patch must therefore not silently create a new authority rule.</p><p>A minimally credible claim test launches two claims against the same TASK at once. Exactly one caller may receive an executable claim credential. The loser must receive a deterministic “already claimed/contention lost” result and must not start a model session or tool call.</p><h3 id="_3-execution-the-rail-dispatches-and-checks-preconditions" tabindex="-1">3. Execution: the rail dispatches and checks preconditions <a class="header-anchor" href="#_3-execution-the-rail-dispatches-and-checks-preconditions" aria-label="Permalink to &quot;3. Execution: the rail dispatches and checks preconditions&quot;">​</a></h3><p>Once the TASK is active, the file state machine says it has been claimed. Code generation, tool mounting, testing, and output capture belong to the engineering runtime.</p><p>The CodeFlowMu V1.9.7 candidate parent implementation routes task mutations through a shared command kernel. A request binds task, root, thread, round, expected revision, and an idempotency key. The following is a structured reading excerpt from private parent commit <code>2c901972df79dc8d0a1e2eee66ed8dce5e4f953f</code>, not CodeFlowMu Open and not publicly cloneable in full. It keeps only the binding fields explained below; omitted fields are neither evidence of absence nor a basis for any capability claim.</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">type</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> TaskCommandRequest</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  task_id</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  root_task_id</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  thread_key</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  expected_revision</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  round_id</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  idempotency_key</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">};</span></span></code></pre></div><p>Three protections follow.</p><p>First, task, root, and canonical thread identity must agree. V1.9.7 normalizes ledger query suffixes so that a lineage bucket is not mistaken for a second task identity:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> function</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> canonicalThreadKey</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">value</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> unknown</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  return</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> String</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(value </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">??</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">).</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">trim</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    .</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">replace</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/</span><span style="--shiki-light:#032F62;--shiki-dark:#DBEDFF;">#TASK-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">{8}</span><span style="--shiki-light:#032F62;--shiki-dark:#DBEDFF;">-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">{3,}</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">.</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">i</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Second, <code>expected_revision</code> rejects a write based on stale facts. If a PM prepared an action against revision A and the task has moved to revision B, the old action cannot be applied unchanged.</p><p>Do not turn an interface field into an unverified algorithm. The inspected private-parent evidence proves only that a command binds and checks <code>expected_revision</code>; it does not disclose whether the value is produced from a content digest, monotonic version, event sequence, or another canonicalization scheme. This article therefore treats it as a precondition token for the current task version, not as an mtime-based mechanism; filesystem modification time cannot carry causal versioning. For any implementation that intends to use such a token to reject stale actions, the minimum engineering requirement is to bind it to version facts that can change that action&#39;s validity and to reject a mismatch; it should not attempt to infer cross-process or cross-device causality from wall-clock time. This is a design requirement in this article, not a claim about V1.9.7&#39;s undisclosed algorithm.</p><p>That also means there is <strong>not yet an assessable versioning closure</strong>. If the token covers the whole TASK content, does appending a <code>transitions</code> event create needless expiry for a concurrent command? If it covers only business content, can an evidence-reference or authorization change evade the stale-action check? The current material does not answer those questions. To test the design, alter body, transition, evidence reference, and authorization scope separately on a fixed task, then replay an old token and observe which changes invalidate the command. Until those results exist, the field cannot be claimed to solve optimistic concurrency control or false aborts.</p><p>Third, the idempotency key distinguishes a transport retry from a new business intent. Replaying the same intent under the same key returns the existing result; reusing the key for a different intent creates a conflict. This reduces duplicate task, attempt, and dispatch creation. It does not prove exactly-once execution for every external tool effect.</p><h3 id="_4-dependencies-not-your-turn-is-not-a-failed-task" tabindex="-1">4. Dependencies: “not your turn” is not a failed task <a class="header-anchor" href="#_4-dependencies-not-your-turn-is-not-a-failed-task" aria-label="Permalink to &quot;4. Dependencies: “not your turn” is not a failed task&quot;">​</a></h3><p>Suppose QA depends on a DEV delivery. The PM creates two distinct child tasks and places an explicit DEV dependency on the QA TASK. CodeFlowMu&#39;s dispatcher can retain the dependent work until the upstream task produces the required completion return.</p><p>The correct meaning is “QA is not eligible yet,” not “QA failed.” Waking QA early and forcing it to write a blocked report would manufacture a business failure from a scheduling error.</p><p>The dependency must also reference the current child task. A thread can contain several rounds of DEV rework. The nearest completed DEV task from an older round must not satisfy the new QA contract.</p><p>There is another question that cannot be skipped: a dependency cycle. If A waits for B and B waits for A, a queue has not created an answer. The inspected V1.9.7 material proves explicit-dependency waiting and release; it does not prove a complete directed acyclic graph (DAG) check. It would be inaccurate to describe automatic exceptional suspension on cycle detection as a current feature.</p><p>A static admission check is not enough either. A running agent may propose a downstream dependency change, but it must not rewrite an existing TASK graph by default. Dependency creation or mutation belongs to PM, ADMIN, or an actor explicitly delegated by the active governance policy. An approved change creates a new task revision, records the actor and policy version, and reruns identity, scope, and cycle checks before dispatch can continue.</p><p>A timeout may report that a policy window was exceeded; it cannot guess which edge to delete or declare business failure. The current material does not prove universal enforcement of dependency-mutation authority, dynamic DAG revalidation, deadlock timeout, or a cycle-breaking protocol. Future dispatcher tests must make an unauthorized edge write and a dependency graph containing a cycle explicit rejection cases: whether the cycle is submitted up front, introduced during execution, or accompanied by prolonged lack of upstream progress, the result should be an inspectable issue for an authorized actor—not indefinite waiting or a heuristic choice of branch.</p><h3 id="_5-return-and-acceptance-executors-submit-authorities-decide" tabindex="-1">5. Return and acceptance: executors submit, authorities decide <a class="header-anchor" href="#_5-return-and-acceptance-executors-submit-authorities-decide" aria-label="Permalink to &quot;5. Return and acceptance: executors submit, authorities decide&quot;">​</a></h3><p>The development agent submits a REPORT bound to the current task and execution round, including inspectable code and test evidence. The TASK may then move to <code>review</code>, where an authorized role accepts or rejects it.</p><p>Two separations must remain intact:</p><ul><li><code>status: done</code> in an agent-authored report is the executor&#39;s claim about its work;</li><li>acceptance is the decision of the PM or ADMIN against the current revision and evidence.</li></ul><p>The <a href="https://github.com/joinwell52-AI/joinwell52/blob/main/docs/public/releases/tmpa/v1.0/artifacts/tmpa-core-specification-s1.0-en.md" target="_blank" rel="noreferrer">TMPA Core Specification S1.0</a> requires role, provenance, and lifecycle to be deterministically reconstructable. CodeFlowMu V1.9.7 likewise models report and acceptance as distinct fact axes. A report can be present while acceptance remains pending.</p><p>This prevents a common premature-completion path: the Runtime observes <code>REPORT-*</code> and turns the root task green. A correct implementation first verifies report attribution, evidence, and current revision, then hands the decision to the authorized actor.</p><h2 id="long-running-commands-need-their-own-execution-lifecycle" tabindex="-1">Long-running commands need their own execution lifecycle <a class="header-anchor" href="#long-running-commands-need-their-own-execution-lifecycle" aria-label="Permalink to &quot;Long-running commands need their own execution lifecycle&quot;">​</a></h2><p>The task lifecycle is not a good place to record every instant of a compiler process. V1.9.7 therefore treats managed commands as an optional Runtime service. Long jobs that must survive session changes, expose continuous logs, recover after Runtime restart, or support precise cancellation can be managed durably. Short tests and builds may still use the host&#39;s native command tools. A short command that does not enter the managed service produces no <code>job.json</code> for that service; its raw output should still be recorded or referenced as REPORT evidence, but the inspected contract does not establish whether that carrier is an attachment, a link, or another form.</p><p>Each managed job is bound to task, session, attempt, and lease information (time-bounded execution ownership). Its per-job <code>job.json</code> is authoritative; the aggregate index is rebuildable. After a restart, the Runtime can rediscover a running or terminal job instead of inferring business outcome from the disappearance of the original agent session.</p><p>Microsoft&#39;s <a href="https://learn.microsoft.com/en-us/windows/win32/procthread/job-objects" target="_blank" rel="noreferrer">Job Objects documentation</a> provides a related operating-system concept: a process group can be managed as a unit. It does not prove that CodeFlowMu uses every Job Object facility. It reinforces the distinction among task lifecycle, model-session lifecycle, and process lifecycle.</p><p>In particular, “short commands may use the host” must not be read as “short commands are already recoverable and terminable.” A host child process outside the managed service has no service-authored <code>job.json</code>, and the current material does not prove that it is uniformly enrolled in a Job Object, parent/child cleanup tree, or orphan-process scan. If an agent session exits unexpectedly, such a command may retain a file, port, or workspace. Production deployment needs separate tests for short-command ownership, timeout termination, residual-handle detection, and failure cleanup. Until evidence exists, this is a risk—not a shipped capability.</p><h2 id="five-invariant-groups-to-test" tabindex="-1">Five invariant groups to test <a class="header-anchor" href="#five-invariant-groups-to-test" aria-label="Permalink to &quot;Five invariant groups to test&quot;">​</a></h2><h3 id="identity" tabindex="-1">Identity <a class="header-anchor" href="#identity" aria-label="Permalink to &quot;Identity&quot;">​</a></h3><ul><li>Each work item has one canonical task identity.</li><li>A child explicitly names its root and parent.</li><li>A report is not attributed solely by thread proximity or wall-clock time.</li></ul><h3 id="state" tabindex="-1">State <a class="header-anchor" href="#state" aria-label="Permalink to &quot;State&quot;">​</a></h3><ul><li>Current state is read from the legal lifecycle location.</li><li>If the same TASK appears in two stages, the conflict is preserved rather than guessed away.</li><li>Body fields cannot override path state.</li></ul><h3 id="transition" tabindex="-1">Transition <a class="header-anchor" href="#transition" aria-label="Permalink to &quot;Transition&quot;">​</a></h3><ul><li>Only enumerated lifecycle transitions are accepted.</li><li>Every transition produces one append-only event.</li><li>Atomicity claims stay inside the documented filesystem boundary.</li></ul><h3 id="execution" tabindex="-1">Execution <a class="header-anchor" href="#execution" aria-label="Permalink to &quot;Execution&quot;">​</a></h3><ul><li>Role capability, task scope, and current revision are rechecked before action.</li><li>A network retry of the same business command does not manufacture duplicate work.</li><li>A dependent agent is not started before an explicit prerequisite is satisfied.</li><li>An executor cannot mutate the dependency graph without explicit authority; an authorized change creates a new revision and reruns identity, scope, and DAG checks.</li><li>Concurrent claim of the same TASK lets only one executor start; a contention loser starts no model session or tool side effect merely because its local call returned.</li></ul><h3 id="acceptance" tabindex="-1">Acceptance <a class="header-anchor" href="#acceptance" aria-label="Permalink to &quot;Acceptance&quot;">​</a></h3><ul><li>A REPORT does not automatically create business acceptance.</li><li>An approval for an old revision does not apply to a new revision.</li><li>An executor cannot unilaterally close work that requires independent acceptance.</li></ul><p>These invariants do not prove that report content is true. They do not replace sandboxing, code review, or security testing. They answer a more basic question: does the system know which work it is handling, where that work is in its lifecycle, which evidence belongs to it, and who may decide the next step?</p><p>A task does not move reliably because its filename is elegant. It moves reliably because <strong>state, history, execution, report, and acceptance retain separate meanings while a stable identity connects them.</strong> That is where the file state machine and the engineering rail genuinely meet.</p><p>This file state machine also has a hard boundary: a single-host <code>rename</code> cannot be promoted into multi-host strong consistency, and a directory timestamp cannot replace a causal revision. Preserving a dual-stage conflict and waiting for authorized recovery prioritizes factual integrity, but it is not an unattended self-healing contract: the current material does not prove a lease, heartbeat, timeout reclamation, write-ahead log, or automatic rollback. It also does not cover every crash point, external tool side effect, or platform. The next validation step is fault injection around write, persistence, and rename, together with double-claim contention, stale-revision replay, dynamic dependency cycles, short-command orphan processes, and authorized recovery of dual-stage conflict. Version files and the live process report V1.9.7, but the release remains a candidate until ADMIN makes the final <code>RELEASED</code> decision.</p><p>The dual-stage conflict described here is not a separate recovery invention. It enters the same <code>unknown_reconcile</code> disposition used elsewhere in this series. A production envelope still needs a named reconciliation owner, opening time, deadline, escalation route, and permitted terminal outcomes; while it waits, the Runtime must not repeatedly wake a model and consume tokens. The inspected V1.9.7 evidence does not yet prove that complete operating contract.</p><h2 id="sources-and-evidence-boundaries" tabindex="-1">Sources and evidence boundaries <a class="header-anchor" href="#sources-and-evidence-boundaries" aria-label="Permalink to &quot;Sources and evidence boundaries&quot;">​</a></h2><p>For how this series distinguishes public specifications, private code excerpts, first-party execution records, and independent material, see <a href="./../methodology/evidence-boundaries">How to Read Engineering Evidence at the Digital Employee Works</a>. The sources below still support only the specific claims stated in this article.</p><ul><li>The <a href="https://github.com/joinwell52-AI/FCoP/blob/main/spec/fcop-3.0-spec.md" target="_blank" rel="noreferrer">FCoP 3.0 specification</a> and <a href="https://github.com/joinwell52-AI/joinwell52/blob/main/docs/public/releases/tmpa/v1.0/artifacts/tmpa-core-specification-s1.0-en.md" target="_blank" rel="noreferrer">TMPA Core S1.0</a> support the descriptions of TASK, REPORT, REVIEW, directory lifecycle, and reconstructible provenance. They do not promise identical behavior on every filesystem.</li><li><a href="https://pubs.opengroup.org/onlinepubs/9799919799/functions/rename.html" target="_blank" rel="noreferrer">POSIX.1-2024 <code>rename()</code></a> supports atomic observation of directory-entry replacement within its stated boundary; it does not support claims about cross-mount transactions, crash durability, or strong network-filesystem consistency.</li><li><a href="https://learn.microsoft.com/en-us/windows/win32/procthread/job-objects" target="_blank" rel="noreferrer">Windows Job Objects</a> document an operating-system mechanism for managing groups of processes. They do not prove that this runtime uses all Job Object capabilities.</li><li>V1.9.7 figures are first-party engineering evidence from a fixed environment, not third-party certification or a cross-platform reliability claim. Accessed 2026-08-23.</li></ul>`,76))])}const b=i(l,[["render",d]]);export{f as __pageData,b as default};
